using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;
namespace Gitpolar.SolidWorks {
  internal sealed class CadPreviewCanvas:PictureBox {
    string message="选择零件或装配体以预览";public string Message{get{return message;}set{message=value;Invalidate();}}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Image==null){CodeIcons.Draw(e.Graphics,"symbol-structure",new Rectangle((Width-30)/2,Math.Max(5,Height/2-45),30,30),Color.FromArgb(118,125,134),28);TextRenderer.DrawText(e.Graphics,message,Dark.Font,new Rectangle(20,Height/2,Math.Max(0,Width-40),Math.Max(0,Height/2-15)),Color.FromArgb(92,99,109),TextFormatFlags.HorizontalCenter|TextFormatFlags.Top|TextFormatFlags.WordBreak|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}}
  }
  internal sealed class EditorListHeader:Control {
    readonly ListView list;public EditorListHeader(ListView list){this.list=list;Dock=DockStyle.Top;Height=30;DoubleBuffered=true;BackColor=Dark.Panel;list.ColumnWidthChanged+=(s,e)=>Invalidate();}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Dark.Panel);int x=0;foreach(ColumnHeader column in list.Columns){TextRenderer.DrawText(e.Graphics,column.Text,Dark.Small,new Rectangle(x+8,0,Math.Max(0,column.Width-12),Height),Dark.Foreground,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);x+=column.Width;}using(var pen=new Pen(Dark.Border))e.Graphics.DrawLine(pen,0,Height-1,Width,Height-1);}
  }
  internal sealed class CodeTree:TreeView {
    public CodeTree(){Dock=DockStyle.Fill;BackColor=Dark.Panel;ForeColor=Dark.Foreground;BorderStyle=BorderStyle.None;Font=Dark.Font;ItemHeight=24;Indent=15;ShowLines=false;ShowPlusMinus=false;ShowRootLines=false;FullRowSelect=true;HideSelection=false;DrawMode=TreeViewDrawMode.OwnerDrawAll;}
    protected override void OnDrawNode(DrawTreeNodeEventArgs e){bool selected=e.Node==SelectedNode;var bounds=new Rectangle(0,e.Bounds.Y,ClientSize.Width,ItemHeight);using(var brush=new SolidBrush(selected?Dark.Selection:BackColor))e.Graphics.FillRectangle(brush,bounds);int x=9+e.Node.Level*Indent;if(e.Node.Nodes.Count>0){CodeIcons.Draw(e.Graphics,e.Node.IsExpanded?"chevron-down":"chevron-right",new Rectangle(x,e.Bounds.Y+4,15,16),Dark.Foreground,14);x+=16;}string glyph=e.Node.Name=="branch"?"git-branch":e.Node.Name=="tag"?"tag":e.Node.Nodes.Count>0?"folder":"file";CodeIcons.Draw(e.Graphics,glyph,new Rectangle(x,e.Bounds.Y+4,16,16),e.Node.Nodes.Count>0?Dark.Muted:Dark.Blue,15);TextRenderer.DrawText(e.Graphics,e.Node.Text,Font,new Rectangle(x+22,e.Bounds.Y,Math.Max(0,Width-x-27),ItemHeight),e.Node.ForeColor.IsEmpty?ForeColor:e.Node.ForeColor,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);var node=GetNodeAt(e.Location);if(node!=null&&node.Nodes.Count>0&&e.X<20+node.Level*Indent)node.Toggle();}
  }
  internal sealed class ChangedFilesTree:Panel {
    readonly CodeTree tree=new CodeTree(){BackColor=Dark.Background};readonly Label title=Dark.Label("CHANGED FILES");bool updating;public event Action<string> FileSelected;public event Action<string> FileOpened;
    public ChangedFilesTree(){Dock=DockStyle.Fill;BackColor=Dark.Background;title.Dock=DockStyle.Top;title.AutoSize=false;title.Height=30;title.Padding=new Padding(9,0,0,0);title.Font=Dark.Small;Controls.Add(tree);Controls.Add(title);tree.AfterSelect+=(s,e)=>{if(!updating&&e.Node.Tag is string&&FileSelected!=null)FileSelected((string)e.Node.Tag);};tree.NodeMouseDoubleClick+=(s,e)=>{if(e.Node.Tag is string&&FileOpened!=null)FileOpened((string)e.Node.Tag);};}
    public void LoadFiles(IEnumerable<ListViewItem> files,string selected){updating=true;tree.BeginUpdate();try{tree.Nodes.Clear();int count=0;foreach(var file in files){count++;string path=Convert.ToString(file.Tag);string[] pieces=path.Split('/');TreeNodeCollection nodes=tree.Nodes;for(int i=0;i<pieces.Length;i++){bool leaf=i==pieces.Length-1;string key=String.Join("/",pieces.Take(i+1));var node=nodes.Cast<TreeNode>().FirstOrDefault(n=>n.Name==key);if(node==null){node=new TreeNode(pieces[i]){Name=key};nodes.Add(node);}if(leaf){node.Tag=path;node.ForeColor=file.ForeColor;if(path==selected)tree.SelectedNode=node;}nodes=node.Nodes;}}title.Text="CHANGED FILES  ·  "+count;tree.ExpandAll();}finally{tree.EndUpdate();updating=false;}}
  }
  internal sealed class CommitSummary:Control {
    Dictionary<string,object> value=new Dictionary<string,object>();string oid="";public CommitSummary(){DoubleBuffered=true;BackColor=Dark.Background;Dock=DockStyle.Top;Height=125;}
    public void Read(Dictionary<string,object> detail,string commit){value=detail;oid=commit;Invalidate();}
    void TextLine(Graphics g,string text,int y,Color color,Font font){TextRenderer.DrawText(g,text,font,new Rectangle(12,y,Width-24,23),color,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix);}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);TextLine(e.Graphics,"COMMIT DETAILS",5,Dark.Muted,Dark.Small);TextLine(e.Graphics,Data.Text(value,"message").Split('\n')[0].Trim(),31,Dark.Foreground,Dark.Font);TextLine(e.Graphics,Data.Text(value,"author"),57,Dark.Foreground,Dark.Font);DateTimeOffset date;string stamp=DateTimeOffset.TryParse(Data.Text(value,"date"),out date)?date.ToLocalTime().ToString("yyyy-MM-dd HH:mm"):Data.Text(value,"date");TextLine(e.Graphics,(oid.Length>7?oid.Substring(0,7):oid)+"  ·  "+stamp,82,Dark.Muted,Dark.Small);using(var pen=new Pen(Dark.Border))e.Graphics.DrawLine(pen,0,Height-1,Width,Height-1);}
  }
  internal sealed class RepositorySidebar:Panel {
    readonly CodeTree tree=new CodeTree();readonly Panel changes=new Panel(){Dock=DockStyle.Top,Height=100};readonly Label changesText=Dark.Label("");string current="";public event Action<string> ReferenceSelected;
    public RepositorySidebar(ComboBox repository,Button save,Button options,EventHandler manage){Width=212;Dock=DockStyle.Left;BackColor=Dark.Panel;var title=new Panel(){Dock=DockStyle.Top,Height=35,BackColor=Dark.Panel};title.Paint+=(s,e)=>TextRenderer.DrawText(e.Graphics,"SOURCE CONTROL",Dark.Small,new Rectangle(16,0,150,35),Dark.Foreground,TextFormatFlags.VerticalCenter|TextFormatFlags.Left);options.Text="";var editor=options as EditorButton;if(editor!=null){editor.Glyph="add";editor.IconOnly=true;}options.AutoSize=false;options.SetBounds(176,3,28,28);title.Controls.Add(options);
      var repoPanel=new Panel(){Dock=DockStyle.Top,Height=36,Padding=new Padding(10,4,10,4)};repository.Dock=DockStyle.Fill;repository.Margin=Padding.Empty;repoPanel.Controls.Add(repository);var savePanel=new Panel(){Dock=DockStyle.Top,Height=40,Padding=new Padding(10,3,10,9)};save.Dock=DockStyle.Fill;save.AutoSize=false;savePanel.Controls.Add(save);
      changes.Paint+=(s,e)=>{CodeIcons.Draw(e.Graphics,"chevron-down",new Rectangle(6,6,15,15),Dark.Foreground,14);TextRenderer.DrawText(e.Graphics,"CHANGES",Dark.Small,new Rectangle(24,0,150,28),Dark.Foreground,TextFormatFlags.VerticalCenter);};changesText.Dock=DockStyle.Fill;changesText.AutoSize=false;changesText.Padding=new Padding(15,30,10,0);changesText.ForeColor=Dark.Muted;changes.Controls.Add(changesText);var branchHead=new Panel(){Dock=DockStyle.Top,Height=30};branchHead.Paint+=(s,e)=>{CodeIcons.Draw(e.Graphics,"chevron-down",new Rectangle(6,6,15,15),Dark.Foreground,14);TextRenderer.DrawText(e.Graphics,"BRANCHES",Dark.Small,new Rectangle(24,0,140,28),Dark.Foreground,TextFormatFlags.VerticalCenter);};var add=EditorLayout.Icon("git-branch","管理分支",manage);add.Dock=DockStyle.Right;branchHead.Controls.Add(add);Controls.Add(tree);Controls.Add(branchHead);Controls.Add(changes);Controls.Add(savePanel);Controls.Add(repoPanel);Controls.Add(title);tree.AfterSelect+=(s,e)=>{if(e.Node.Tag is string&&ReferenceSelected!=null)ReferenceSelected((string)e.Node.Tag);};
    }
    public void Read(IEnumerable<GraphRef> references,Dictionary<string,object> state){current=Data.Text(state,"branch");changesText.Text=Data.Array(state,"files").Length==0?"✓  工作副本已保存\r\n\r\n没有未提交的改动":String.Join("\r\n",Data.Array(state,"files").Take(3).Select(Data.Map).Select(file=>Data.Text(file,"status")+"  "+Path.GetFileName(Data.Text(file,"path"))));tree.BeginUpdate();try{tree.Nodes.Clear();foreach(string type in new string[]{"branch","remote","tag"}){var entries=references.Where(r=>r.Type==type).ToArray();if(entries.Length==0)continue;var parent=tree.Nodes.Add(type=="branch"?"本地":type=="remote"?"远端":"标签");foreach(var reference in entries)parent.Nodes.Add(new TreeNode(reference.Name+(reference.Name==current?"  ✓":"")){Name=type=="tag"?"tag":"branch",Tag=reference.FullName,ForeColor=reference.Name==current?Dark.Foreground:Dark.Muted});}tree.ExpandAll();}finally{tree.EndUpdate();}}
  }
  internal sealed class ManualMergeView:Control {
    Dictionary<string,object> state=new Dictionary<string,object>();public ManualMergeView(){Dock=DockStyle.Fill;DoubleBuffered=true;BackColor=Dark.Background;}
    public void Read(Dictionary<string,object> value){state=value;Invalidate();}
    void Line(Graphics g,string text,Rectangle bounds,Color color,Font font){TextRenderer.DrawText(g,text,font,bounds,color,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix);}
    void Card(Graphics g,string title,string oid,int x,int y,int width,Color color){using(var brush=new SolidBrush(Dark.Panel))g.FillRectangle(brush,x,y,width,94);using(var brush=new SolidBrush(color))g.FillRectangle(brush,x,y,3,94);CodeIcons.Draw(g,"git-branch",new Rectangle(x+16,y+15,20,20),color,18);Line(g,title,new Rectangle(x+45,y+10,width-60,30),Dark.Foreground,Dark.Font);Line(g,oid.Length==0?"等待选择装配体":oid.Substring(0,Math.Min(12,oid.Length)),new Rectangle(x+17,y+49,width-32,28),Dark.Muted,Dark.Mono);}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;int width=Width-48;string phase=Data.Text(state,"state");int completed=phase=="completed"?4:phase=="applied"?3:phase=="editing"?1:0;string[] labels={"导入分支装配","手工合图","应用人工结果","完成合并"};int cell=Math.Max(140,width/4);for(int i=0;i<4;i++){int x=24+i*cell;Color color=i<completed?Color.FromArgb(78,201,176):i==completed?Dark.Blue:Dark.Muted;using(var pen=new Pen(color,1))g.DrawEllipse(pen,x,24,23,23);Line(g,i<completed?"✓":(i+1).ToString(),new Rectangle(x+6,24,18,23),color,Dark.Small);Line(g,labels[i],new Rectangle(x+34,20,cell-40,30),color,Dark.Font);if(i<3)using(var pen=new Pen(Dark.Border))g.DrawLine(pen,x+30,59,x+cell-10,59);}
      int cardWidth=(width-16)/2;Card(g,"A  当前分支",Data.Text(state,"ours"),24,85,cardWidth,Dark.Lanes[0]);Card(g,"B  合入分支",Data.Text(state,"theirs"),40+cardWidth,85,cardWidth,Dark.Lanes[2]);CodeIcons.Draw(g,"git-merge",new Rectangle(24,207,23,23),Dark.Blue,22);Line(g,phase=="completed"?"合并结果已保存":phase=="applied"?"结果已应用 · 可以完成合并":"在 SolidWorks 中编辑两边装配",new Rectangle(59,200,width-40,34),Dark.Foreground,Dark.Font);string target=Data.Text(state,"target");Line(g,target.Length==0?"选择两边的总装后，导入到一个临时装配体。":target,new Rectangle(24,246,width,27),Dark.Foreground,Dark.Font);Line(g,phase=="completed"?"Merge  "+Data.Text(state,"commit"):"编辑完成后，点击“应用人工结果”核对写回路径。",new Rectangle(24,278,width,27),Dark.Muted,phase=="completed"?Dark.Mono:Dark.Font);int y=326;foreach(string path in Data.Array(state,"applied").Select(Convert.ToString)){CodeIcons.Draw(g,"file",new Rectangle(26,y+3,17,17),Dark.Blue,15);Line(g,path,new Rectangle(52,y,width-26,25),Dark.Foreground,Dark.Font);y+=27;}
    }
  }
}
